<script setup lang="ts">
import {computed,ref} from 'vue';import {onLoad,onShow,onHide} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {managementGo} from '@/shared/management';import {money} from '@shared/utils/money';import {idempotencyKey} from '@shared/net/http-client';import {definiteGovernanceRejection} from '@/shared/stored-value-governance-errors';import type {SvFinanceResource,SvFinanceCapability,SvSettlementBill,SvGenerationRequest} from '@/api/stored-value-finance';
const {t}=useI18n();const m=ref(''),actor=ref(''),scope=ref<'BRAND'|'STORE'|''>(''),issuer=ref(''),status=ref('');const resources=ref<SvFinanceResource[]>([]),bills=ref<SvSettlementBill[]>([]),next=ref<string|null>(null),capability=ref<SvFinanceCapability|null>(null);const loading=ref(true),failed=ref(false),busy=ref(false),choosing=ref(false),creating=ref(false),error=ref('');const from=ref(''),to=ref('');
type Pending={body:SvGenerationRequest;key:string};const pending=ref<Pending|null>(null);const storage=computed(()=>['sv-generation',actor.value,m.value].map(encodeURIComponent).join(':'));const selected=computed(()=>resources.value.find(x=>x.issuerNo===issuer.value));const tabs=computed(()=>['','DRAFT','RECONCILED','DISPUTED','SETTLED'].map(key=>({key,label:t('svFinance.states.'+(key||'ALL'))})));
let generation=0;
async function load(append=false){if(append&&loading.value)return;const run=++generation;if(!append)next.value=null;loading.value=true;failed.value=false;try{const p=await api.mSvSettlementBills({managementNo:m.value,...(scope.value?{scopeType:scope.value}:{}),...(issuer.value?{issuerNo:issuer.value}:{}),...(status.value?{status:status.value}:{}),...(append&&next.value?{cursor:next.value}:{})});if(run!==generation)return;bills.value=append?[...bills.value,...p.records]:p.records;next.value=p.nextCursor}catch(e){if(run===generation){failed.value=true;error.value=(e as Error).message}}finally{if(run===generation)loading.value=false}}
async function init(){const run=++generation;loading.value=true;failed.value=false;try{const identity=await api.mManagementContext();if(run!==generation)return;actor.value=identity.actorKey;pending.value=null;creating.value=false;const result=await Promise.all([api.mSvFinanceResources(m.value,scope.value||undefined),api.mSvFinanceCapability()]);if(run!==generation)return;[resources.value,capability.value]=result;const saved=uni.getStorageSync(storage.value);if(saved){pending.value=JSON.parse(String(saved));if(pending.value?.body.managementNo!==m.value)pending.value=null;else{issuer.value=pending.value.body.issuerNo;from.value=pending.value.body.periodFrom;to.value=pending.value.body.periodTo;creating.value=selected.value?.canGenerate===true}}if(resources.value.length)await load();else{bills.value=[];next.value=null}}catch(e){if(run===generation){failed.value=true;error.value=(e as Error).message}}finally{if(run===generation)loading.value=false}}
async function generate(){if(busy.value||!selected.value||selected.value.canGenerate!==true||(!pending.value&&!capability.value?.settlementReady))return;error.value='';try{if(!pending.value){if(!from.value||!to.value||from.value>=to.value)throw Error(t('svFinance.invalidPeriod'));pending.value={body:{managementNo:m.value,issuerNo:issuer.value,periodFrom:from.value,periodTo:to.value,currency:selected.value.currency},key:idempotencyKey()};uni.setStorageSync(storage.value,JSON.stringify(pending.value))}busy.value=true;await api.mSvSettlementGenerate(pending.value.body,pending.value.key);uni.removeStorageSync(storage.value);pending.value=null;creating.value=false;await load()}catch(e){error.value=(e as Error).message;if(definiteGovernanceRejection(e)){pending.value=null;uni.removeStorageSync(storage.value)}}finally{busy.value=false}}
function choose(r:SvFinanceResource){if(pending.value)return;issuer.value=r.issuerNo;choosing.value=false;void load()}
onLoad(q=>{m.value=q?.m||'';issuer.value=q?.issuer||'';scope.value=q?.scope==='STORE'?'STORE':q?.scope==='BRAND'?'BRAND':''});onShow(init);
onHide(()=>{generation++;bills.value=[];resources.value=[];next.value=null;loading.value=false});
</script>
<template><sh-scaffold title-key="svFinance.settlement" :pending="loading" :failed="failed" @retry="init"><view v-if="resources.length" class="sh-card sh-row sh-row--between" @tap="choosing=true"><text>{{selected?.name||t('svFinance.chooseIssuer')}}</text><sh-go/></view><sh-tabs :items="tabs" :active="status" @change="status=$event;load()"/>
 <view v-for="bill in bills" :key="bill.billNo" class="sh-card sh-hit" @tap="managementGo('storedValueSettlementDetail',{m,bill:bill.billNo})"><view class="sh-row sh-row--between"><text class="txt-strong">{{resources.find(x=>x.issuerNo===bill.issuerNo)?.name||bill.billNo}}</text><text class="sh-chip">{{t('svFinance.states.'+bill.status)}}</text></view><sh-kv :label="t('svFinance.payableMinor')" between>{{money(bill.payableMinor,bill.currency)}}</sh-kv><sh-kv :label="t('svFinance.confirmed')" between>{{money(bill.confirmedReceiptMinor,bill.currency)}}</sh-kv><text class="txt-sub sh-muted">{{bill.periodFrom.slice(0,10)}} — {{bill.periodTo.slice(0,10)}}</text></view><sh-empty v-if="!loading&&!bills.length" :text="t('svFinance.empty')"/><view v-if="next" class="sh-btn sh-btn--soft" @tap="load(true)">{{t('svGov.more')}}</view><text v-if="error" class="sh-hint">{{error}}</text>
 <sh-actionbar v-if="capability?.settlementReady&&selected?.canGenerate===true"><view data-testid="finance-generate-open" class="sh-btn" @tap="creating=true">{{t('svFinance.generate')}}</view></sh-actionbar>
 <sh-sheet :visible="choosing" :title="t('svFinance.chooseIssuer')" @close="choosing=false"><view v-for="r in resources" :key="r.issuerNo" class="sh-cell sh-row sh-row--between" @tap="choose(r)"><text>{{r.name}} · {{r.currency}}</text><sh-go/></view></sh-sheet>
 <sh-sheet :visible="creating" :title="t('svFinance.generate')" @close="!pending&&!busy&&(creating=false)"><view class="sh-card"><text class="txt-strong">{{selected?.name}}</text><picker mode="date" :value="from" :disabled="!!pending" @change="from=$event.detail.value"><view class="sh-cell">{{t('svGov.startDate')}} · {{from||'—'}}</view></picker><picker mode="date" :value="to" :disabled="!!pending" @change="to=$event.detail.value"><view class="sh-cell">{{t('svFinance.endExclusive')}} · {{to||'—'}}</view></picker></view><text v-if="pending" class="sh-hint">{{t('svGov.unknown')}}</text><text v-if="error" class="sh-hint">{{error}}</text><view class="sh-btn" :class="{'is-disabled':busy}" @tap="generate">{{t(pending?'svGov.retry':'svFinance.generate')}}</view></sh-sheet>
</sh-scaffold></template>
